function useItem(item){if(item==='bandage'){if(state.bandage<=0){notify('NO FIELD DRESSINGS');return}if(state.hp>=100){notify('HEALTH ALREADY FULL');return}state.bandage--;state.hp=Math.min(100,state.hp+35);notify('FIELD DRESSING USED  +35 HEALTH')}if(item==='food'){if(state.food<=0){notify('NO FOOD');return}state.food--;state.hunger=Math.min(100,state.hunger+38);state.stamina=Math.min(100,state.stamina+12);notify('CANNED FOOD EATEN')}if(item==='water'){if(state.water<=0){notify('NO WATER');return}state.water--;state.thirst=Math.min(100,state.thirst+42);notify('WATER CONSUMED')}updateHud();save()}
