import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } })
page.on('pageerror', e => console.error('PAGEERROR', e.message))
await page.goto('http://127.0.0.1:4173', { waitUntil: 'load' })
await page.evaluate(() => localStorage.clear())
await page.reload({ waitUntil: 'load' })
console.log(await page.locator('#startBtn').evaluate(e => ({rect: e.getBoundingClientRect().toJSON(), style: {display:getComputedStyle(e).display, visibility:getComputedStyle(e).visibility, opacity:getComputedStyle(e).opacity}, parent: e.parentElement.getBoundingClientRect().toJSON(), screenClass:e.closest('.title-screen').className, hidden:e.hidden})))
await page.screenshot({path:'/tmp/opencode/ashes-debug.jpg',type:'jpeg',quality:70})
await browser.close()

