+function save(){state.x=player.x;state.used=interactables.filter(i=>i.used).map(i=>i.x);state.enemyState=enemies.map(e=>({x:e.x,hp:e.hp,alert:e.alert,dead:e.dead,fade:e.fade||0}));try{localStorage.setItem('ashes-save',JSON.stringify(state));hasSave=true;updateContinueButton();el('saveStatus').innerHTML='●&nbsp; FIELD LOG SYNCED';setTimeout(()=>{if(el('saveStatus'))el('saveStatus').innerHTML='●&nbsp; FIELD LOG SYNCED'},500)}catch{}}
 function notify(msg){const t=el('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
 function setObjective(title,text,objective,step){el('questTitle').textContent=title;el('questText').textContent=text;el('objectiveText').textContent=objective;el('questProgress').style.width=step===0?'18%':step===1?'42%':step===2?'66%':step===3?'86%':'100%';el('objectiveCheck').classList.toggle('done',step>state.step);}
 function updateQuest(){const s=state.step;if(s===0)setObjective('A SIGNAL IN THE STATIC','A voice cuts through the emergency band. Find where it comes from.','Reach the old relay station',s);if(s===1)setObjective('A VOICE IN THE DARK','The signal carried a name: Blacksite. Find someone who knows the road.','Speak with the wandering medic',s);if(s===2)setObjective('NO SAFE PASSAGE','A military checkpoint blocks the road. Search for a way through.','Reach the North checkpoint',s);if(s===3)setObjective('THE BLACKSITE','The broadcast was no accident. Find the underground facility.','Enter the Blacksite access',s);if(s===4)setObjective('PATIENT ZERO','The source is below. Recover the truth — then choose what survives.','Reach the containment vault',s);if(s>=5)setObjective('ASHES OF TOMORROW','Some truths cannot be buried.','The ending is yours to carry',s)}
+function restoreRun(snapshot){state={...initial,...snapshot,found:[...(snapshot.found||[])],visited:[...(snapshot.visited||[])],used:[...(snapshot.used||[])]};player.x=clamp(Number(state.x)||initial.x,35,WORLD-35);player.y=GROUND;player.vx=player.vy=0;player.onGround=true;player.invuln=player.attack=player.walk=0;enemies.length=0;enemyBlueprint.forEach((spec,index)=>{mkEnemy(spec.x,spec.type);if(state.enemyState?.[index])Object.assign(enemies[index],state.enemyState[index])});bullets.length=enemyBullets.length=particles.length=0;interactables.forEach(i=>{i.used=state.used.includes(i.x)||(i.type==='relay'&&state.step>0)||(i.type==='survivor'&&state.step>1)||(i.type==='lab'&&state.step>3)||(i.type==='sample'&&state.step>4)});gameOver=false;updateQuest();updateHud()}
