import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } })
const errors = []
page.on('pageerror', e => errors.push(e.message))
const assert = (ok, message) => { if (!ok) throw new Error(message); console.log('PASS', message) }
await page.goto('http://127.0.0.1:4173', { waitUntil: 'load' })
const base = { hp:82, stamina:74, hunger:68, thirst:54, temp:31, ammo:8, reserve:24, bandage:2, food:1, water:2, scrap:3, meds:1, xp:40, level:3, weapon:'SERVICE PISTOL', kills:0, found:[], choice:null, visited:[], used:[], day:6 }
async function loadAt(step, x, patch = {}) {
  await page.evaluate(({save}) => localStorage.setItem('ashes-save', JSON.stringify(save)), { save: {...base, step, x, ...patch} })
  await page.reload({ waitUntil:'load' })
  await page.locator('#continueBtn').evaluate(e => e.click())
}
async function interactAt(step, x, expectedText) {
  await loadAt(step, x)
  await page.keyboard.press('e')
  assert((await page.locator('#modal').innerText()).includes(expectedText), `step ${step} interaction opens ${expectedText}`)
}
await page.evaluate(() => localStorage.clear())
await page.reload({waitUntil:'load'})
await page.locator('#startBtn').evaluate(e => e.click())
await page.keyboard.press('e')
assert((await page.locator('#modal').innerText()).includes('A VOICE IN THE STATIC'), 'relay starts the signal story')
await page.locator('[data-action="close"]').evaluate(e => e.click())
assert((await page.evaluate(() => JSON.parse(localStorage.getItem('ashes-save')))).step === 1, 'relay progress saves')
await interactAt(1, 1800, 'THE WANDERING MEDIC')
await page.locator('[data-action="close"]').evaluate(e => e.click())
assert((await page.evaluate(() => JSON.parse(localStorage.getItem('ashes-save')))).step === 2, 'medic advances and saves progression')
for (const choice of ['sneak','fight']) {
  await interactAt(2, 2660, 'NO SAFE PASSAGE')
  await page.locator(`[data-action="${choice}"]`).evaluate(e => e.click())
  const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('ashes-save')))
  assert(saved.step === 3 && saved.used.includes(2660), `${choice} checkpoint path clears checkpoint and saves`)
}
await interactAt(3, 4020, 'THE BLACKSITE')
await page.locator('[data-action="close"]').evaluate(e => e.click())
assert((await page.evaluate(() => JSON.parse(localStorage.getItem('ashes-save')))).step === 4, 'Blacksite access advances and saves')
const endings = [
  ['cure', 'A PROMISE IN THE RUINS'],
  ['destroy', 'NO SECOND DAWN'],
  ['keep', 'THE WEIGHT OF TOMORROW'],
]
for (const [choice, title] of endings) {
  await loadAt(4, 5230)
  await page.keyboard.press('e')
  assert((await page.locator('#modal').innerText()).includes('WHAT REMAINS'), `${choice} route reaches ending decision`)
  await page.locator(`[data-action="ending-${choice}"]`).evaluate(e => e.click())
  assert((await page.locator('#modal').innerText()).includes(title), `${choice} choice resolves to its ending`) 
  const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('ashes-save')))
  assert(saved.choice === choice && saved.step === 5, `${choice} ending is persisted`)
  await page.locator('[data-action="title"]').evaluate(e => e.click())
  await page.locator('#continueBtn').evaluate(e => e.click())
  assert(await page.locator('#screenOverlay').evaluate(e => !e.classList.contains('open')), `${choice} completed run continues without replaying choice`)
}
assert(errors.length === 0, `no browser runtime errors${errors.length ? ': '+errors.join('; ') : ''}`)
await browser.close()
